// Open-source licenses shown in Settings. The data is generated by
// scripts/app-licenses/generate.mjs into assets/notices/licenses.json.

export interface LicenseItem {
  name: string;
  version?: string;
  license: string;
  url?: string;
  platforms?: string[];
  note?: string;
  /** Key into LicenseData.texts. */
  text?: string;
  /** Packages compiled into this item, such as Mermaid's dependencies. */
  includes?: LicenseItem[];
}

export interface LicenseSection {
  title: string;
  items: LicenseItem[];
}

export interface LicenseData {
  sections: LicenseSection[];
  texts: Record<string, string>;
}

let cached: LicenseData | null = null;

/** Loads the generated data on first use, not at app start. */
export function openSourceLicenses(): LicenseData {
  cached ??= require("../assets/notices/licenses.json") as LicenseData;
  return cached;
}

/** Id of an item for the detail route: "<section>/<item>[/<included item>]". */
export function licenseItemId(...indices: number[]): string {
  return indices.join("/");
}

export function findLicenseItem(data: LicenseData, id: string | undefined): LicenseItem | null {
  if (!/^\d+\/\d+(\/\d+)?$/.test(id ?? "")) return null;
  const [section, index, included] = id!.split("/").map(Number);
  const item = data.sections[section]?.items[index] ?? null;
  if (included === undefined) return item;
  return item?.includes?.[included] ?? null;
}

const PLATFORM_NAMES: Record<string, string> = { android: "Android", ios: "iOS" };

/** "1.2.3 · MIT · Android only" */
export function licenseSummary(item: LicenseItem): string {
  const parts = [item.version, item.license];
  if (item.platforms?.length === 1) {
    parts.push(`${PLATFORM_NAMES[item.platforms[0]] ?? item.platforms[0]} only`);
  }
  const included = item.includes?.length ?? 0;
  if (included > 0) parts.push(`includes ${included} ${included === 1 ? "package" : "packages"}`);
  return parts.filter(Boolean).join(" · ");
}
